={
  "messaging_product": "whatsapp",
  "recipient_type": "individual",
  "to": "{{$json["painter_mobile"]}}",
  "type": "interactive",
  "interactive": {
    "type": "cta_url",
    "header": {
      "type": "text",
      "text": "Today's Site Visit Scheduled"
    },
    "body": {
      "text": "Hello {{$json["painter_name"]}},\nYou have a site visit scheduled for today:\n\nCustomer: {{$json["site_owner_name"]}}\nTime: {{$json["formatted_visit_time"]}}\nLocation: {{$json["address_line1"]}}, {{$json["town"]}}\nCarpet Area: {{$json["carpet_area"]}} sq ft\nBudget: {{$json["budget_range"]}}\n\nCheck your complete schedule and open leads calendar via the link below."
    },
    "action": {
      "name": "cta_url",
      "parameters": {
        "display_text": "View Calendar",
        "url": "https://lms-berger-ui.vercel.app/painter-calendar.html?painter_id={{$json["painter_id"]}}"
      }
    }
  }
}

={
  "messaging_product": "whatsapp",
  "recipient_type": "individual",
  "to": "{{$json["site_owner_mobile"]}}",
  "type": "text",
  "text": {
    "body": "Dear {{$json["site_owner_name"]}},\nThis is a friendly reminder that your painting site consultation visit is scheduled for today at {{$json["formatted_visit_time"]}}.\n\nYour Assigned Painter:\nName: {{$json["painter_name"]}}\nMobile: {{$json["painter_mobile"]}}\n\nThank you for choosing Berger Paints!"
  }
}
